document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target==='_blank'||link.hasAttribute('download'))return;const url=new URL(link.href,window.location.href);if(url.origin!==window.location.origin||url.pathname===window.location.pathname)return;if(window.CSS?.supports('view-transition-name: root'))return;event.preventDefault();document.body.classList.add('page-leaving');window.setTimeout(()=>{window.location.href=url.href},780)});window.addEventListener('pageshow',()=>document.body.classList.remove('page-leaving'));
const revealSelector='.hero-panel>*,.stat,.intro-grid>*,.section-head>*,.structure-card,.event-row,.page-hero .wrap>*,.board-label,.member,.benefit,.program-summary>*,.program,.cta-grid>*,.analyst-overview>.wrap>.section-kicker,.analyst-overview>.wrap>.section-title,.contact-band .wrap>*,.contact-info .wrap>*';
const revealItems=[...document.querySelectorAll(revealSelector)];
const revealSet=new Set(revealItems);
revealItems.forEach(item=>{item.classList.add('reveal-item');const siblings=[...item.parentElement.children].filter(sibling=>revealSet.has(sibling));const position=Math.max(0,siblings.indexOf(item));item.style.setProperty('--reveal-delay',Math.min(position*35,140)+'ms')});
let revealStarted=false;
function startReveal(){if(revealStarted)return;revealStarted=true;if(!('IntersectionObserver'in window)){revealItems.forEach(item=>item.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.08,rootMargin:'0px 0px -5%'});revealItems.forEach(item=>observer.observe(item))}
if('onpagereveal'in window){window.addEventListener('pagereveal',event=>{if(event.viewTransition)event.viewTransition.finished.then(()=>window.setTimeout(startReveal,80));else startReveal()},{once:true})}else window.setTimeout(startReveal,120);
window.setTimeout(startReveal,1400);
